SourceCode.Declaration:
/// <summary>
/// Class is used to make copy of <c>GUPPriceTermJournalTable</c> records. Should be called from form GUPPriceTermJournalTable.
/// </summary>
internal final class GUPPriceTermJournalTableCopy
{
    private GUPPriceTermJournalTable    gupPriceTermJournalTableOrig;
    private FormDataSource              gupPriceTermJournalTable_ds;

    #OCCRetryCount

}

Method.Source:
public void new(GUPPriceTermJournalTable _journalTable, FormDataSource _formDatasource = null)
{
    // Load price term agreement, or reference will change with form datasource.
    this.gupPriceTermJournalTableOrig   = GUPPriceTermJournalTable::find(_journalTable.AgreementId);
    this.gupPriceTermJournalTable_ds    = _formDatasource;
}

public static void main(Args _args)
{
    if (_args && _args.record() && _args.record().TableId == tableNum(GUPPriceTermJournalTable))
    {
        Object gupPriceTermJournalTable_ds = FormDataUtil::getFormDataSource(_args.record());
        GUPPriceTermJournalTableCopy gupPriceTermJournalTableCopy = new GUPPriceTermJournalTableCopy(_args.record(), gupPriceTermJournalTable_ds);

        gupPriceTermJournalTableCopy.run();
    }
    else
    {
        throw error(strFmt("@SYS27147", new DictClass(classNum(GUPPriceTermJournalTableCopy)).name()));
    }
}

private void run()
{
    GUPPriceTermJournalTable    gupPriceTermJournalTableNew;

    try
    {
        if (this.checkNumSeqExists())
        {
            ttsbegin;
            gupPriceTermJournalTable_ds.create(true);
            gupPriceTermJournalTableNew = this.copyTable(gupPriceTermJournalTableOrig);
            gupPriceTermJournalTableNew = gupPriceTermJournalTable_ds.cursor();
            gupPriceTermJournalTable_ds.write();
            this.createLine(gupPriceTermJournalTableOrig.AgreementId, gupPriceTermJournalTableNew);
            ttscommit;
        }
        else
        {
            GUPAgreementId agreementid = this.getJournalNumFromDialog(gupPriceTermJournalTableOrig.AgreementId);

            if(agreementid)
            {
                ttsbegin;
                gupPriceTermJournalTableNew = this.copyTable(gupPriceTermJournalTableOrig);
                gupPriceTermJournalTableNew = gupPriceTermJournalTable_ds.cursor();
                gupPriceTermJournalTableNew.AgreementId = agreementid;
                gupPriceTermJournalTableNew.insert();
                this.createLine(gupPriceTermJournalTableOrig.AgreementId, gupPriceTermJournalTableNew);
                gupPriceTermJournalTable_ds.research(1);
                ttscommit;
            }
        }
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::Error)
    {
        ttsabort;
        Box::stop("@GLS110288");
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

    private GUPPriceTermJournalTable copyTable(GUPPriceTermJournalTable _gupPriceTermJournalTableOrig)
    {
        GUPPriceTermJournalTable    gupPriceTermJournalTableNew;

		// Copy table
        gupPriceTermJournalTableNew.InventSiteId    = _gupPriceTermJournalTableOrig.InventSiteId;
        gupPriceTermJournalTableNew.ValidFrom       = _gupPriceTermJournalTableOrig.ValidFrom;
        gupPriceTermJournalTableNew.ValidTo         = _gupPriceTermJournalTableOrig.ValidTo;
        gupPriceTermJournalTableNew.VendCust        = _gupPriceTermJournalTableOrig.VendCust;
		gupPriceTermJournalTableNew.Status          = GUPDisabledEnabled::Disabled;

        return gupPriceTermJournalTableNew;
    }

private void createLine(GUPAgreementId _agreementIdOrig, GUPPriceTermJournalTable _gupPriceTermJournalTableNew)
{
    GUPPriceTermJournalTrans    gupPriceTermJournalTransNew, gupPriceTermJournalTransOrig;

    while select gupPriceTermJournalTransOrig
        where gupPriceTermJournalTransOrig.AgreementId == _agreementIdOrig
    {
        gupPriceTermJournalTransNew.clear();
        gupPriceTermJournalTransNew.initfromGUPPriceTermJournalTrans(gupPriceTermJournalTransOrig);
        gupPriceTermJournalTransNew.initfromGUPPriceTermJournalTable(_gupPriceTermJournalTableNew);
        gupPriceTermJournalTransNew.InventDimId = gupPriceTermJournalTransOrig.InventDimId;
        gupPriceTermJournalTransNew.LineNum     = GUPPriceTermJournalTrans::lastLineNum(gupPriceTermJournalTransNew.AgreementId) + 1;
        gupPriceTermJournalTransNew.PricingRule = GUPPricingRule::find(gupPriceTermJournalTransOrig.PricingRule).copy().RecId;
        if (!gupPriceTermJournalTransNew.ValidFrom ||
            gupPriceTermJournalTransNew.ValidFrom != gupPriceTermJournalTransOrig.ValidFrom)
        {
            gupPriceTermJournalTransNew.ValidFrom = gupPriceTermJournalTransOrig.ValidFrom;
        }
        if (!gupPriceTermJournalTransNew.ValidTo ||
            gupPriceTermJournalTransNew.ValidTo != gupPriceTermJournalTransOrig.ValidTo)
        {
            gupPriceTermJournalTransNew.ValidTo = gupPriceTermJournalTransOrig.ValidTo;
        }
        gupPriceTermJournalTransNew.insert();
    }
}

private GUPAgreementId getJournalNumFromDialog(GUPAgreementId _AgreementId)
{
    Args				args = new Args();
    GUPAgreementId		agreementId;

    args.parm(_AgreementId);
    args.caller(this);
    args.name(formstr(GUPJournalIdDialog));

    FormRun	formRun = classFactory.formRunClass(Args);

    formRun.init();
    formRun.run();
    formRun.wait();

    if (formRun.closedOk())
    {
        agreementId = formRun.getJourId();
    }

    return agreementId;
}
